      "card_id": "champ:523:system:p:thehitmanandtheseer:recognize:L2",
      "core_coverage": [
        {
          "answer_quote": "Aphelios equips two of five weapons with distinct attacks and abilities; the main-hand determines his active, and weapon actives have separate cooldowns.",
          "covered": true,
          "mechanic_id": "system_equipment",
          "reason": "Explains equipment, main-hand selection and the supported independent-cooldown interaction."
        },
        {
          "answer_quote": "Basic attacks and weapon-active casts spend ammunition, but automatic attacks caused by abilities spend no additional ammunition; an empty weapon moves to the queue's end and is replaced by the next reserve weapon.",
          "covered": true,
          "mechanic_id": "system_ammo_cycle",
          "reason": "Explains consumption, the automatic-attack exemption, replacement and queue cycling."
        },
        {
          "answer_quote": "He starts with Calibrum main-hand and Severum off-hand, then Gravitum, Infernum and Crescendum in reserve; E shows the next weapon and can display a text prompt.",
          "covered": true,
          "mechanic_id": "system_queue_indicator",
          "reason": "Gives the correct starting arrangement and explains E as a display and prompt."
        },
        {
          "answer_quote": "Phase is available from the start, weapon actives unlock at level 2, and Moonlight Vigil unlocks at level 6 and improves at levels 11 and 16; skill points grant attack damage, attack speed or lethality instead of ability ranks.",
          "covered": true,
          "mechanic_id": "system_unlocks",
          "reason": "All unlock levels and alternative skill-point uses match the evidence."
        }
